KG42.register("rules-bf3946560d84d6aad9b54aec",{"id":"17-exogenous_cost_allocation::v141-c-R008","paper":"17-exogenous_cost_allocation","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Each agent's signed monetary outcome equals the sum of bilateral trading prices multiplied by traded powers, minus its network-charge allocation, including the constant charge term. The network-charge portion is reserved to the system operator. Scope: Bilateral real-power trades of each P2P market agent per market time unit. Bilateral monetary obligations include an energy-generation-cost component supplemented by a network-charge component that can recover network costs and other operational, tax and policy-related costs. Scope: Cost components of the proposed P2P bilateral contracts. The fee mechanism covers real-power trades only; reactive-power injection fees are outside its stated scope. Scope: Trade fees considered in the proposed P2P cost-allocation mechanism. Each trade endpoint's network-charge coefficient has magnitude one half of the unique unit fee, with its sign chosen so that the charge contribution for the traded quantity is nonnegative. Scope: Network-charge component of bilateral settlement under the unique cost-allocation policy. Condition: Both ends of a trade are assigned equal responsibility. Each trade endpoint's network-charge coefficient has magnitude one half of the distance unit fee multiplied by the electrical distance between the trading agents. Scope: Network-charge component of bilateral settlement under the electrical-distance cost-allocation policy. Condition: Both ends of a trade share responsibility equally and the prescribed charge-sign convention is followed. Each trade endpoint's network-charge coefficient has magnitude one half of the uniform zonal unit fee multiplied by the number of zones crossed by the trade. Scope: Network-charge component of bilateral settlement under the illustrative uniform-zonal-unit-fee policy. Condition: Costs are shared equally between both ends of a trade and the prescribed charge-sign convention is conserved.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["settlement.payment"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Bilateral real-power trades of each P2P market agent per market time unit. | Cost components of the proposed P2P bilateral contracts. | Network-charge component of bilateral settlement under the electrical-distance cost-allocation policy. | Network-charge component of bilateral settlement under the illustrative uniform-zonal-unit-fee policy. | Network-charge component of bilateral settlement under the unique cost-allocation policy. | Trade fees considered in the proposed P2P cost-allocation mechanism.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e24","v141-b-g01-e25","v141-b-g01-e26","v141-b-g01-e27","v141-b-g02-E13"]},"x":[{"variable_id":"x_p_nm","symbol":"p_{nm}","meaning":"Bilateral real-power trade from agent n to agent m, entering agent n's payment; positive for production/sale and negative for consumption/purchase in the source sign convention.","kind":"operational","domain":"Real-valued traded power for m in omega_n, with p_nm=0 outside n's trading partnership set and subject to the source role and power-bound constraints.","unit":"MW","indices":["n","m"],"evidence_ids":["v141-b-g01-e24","v141-b-g01-e10","v141-b-g01-e09"]},{"variable_id":"x_lambda_nm","symbol":"\\lambda_{nm}","meaning":"Bilateral trading price, described by the source as the generation price of electricity for traded volume p_nm; treated here as the price input to the settlement payment relation.","kind":"operational","domain":"Real-valued for each ordered pair (n,m) with m in omega_n; determined through the negotiation price update rather than fixed by the payment equation itself.","unit":"€/MWh","indices":["n","m"],"evidence_ids":["v141-b-g01-e18","v141-b-g01-e17","v141-b-g01-e24"]}],"theta":[{"parameter_id":"theta_gamma_nm","symbol":"\\gamma_{nm}","meaning":"Network charge associated with the real-power trade p_nm, provided a priori by the system operator under the chosen cost-allocation policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/MWh","indices":["n","m"],"evidence_ids":["v141-b-g01-e13","v141-b-g01-e24","v141-b-g01-e26"]},{"parameter_id":"theta_gamma_n0","symbol":"\\gamma_n^0","meaning":"Constant network-charge term for agent n, reflecting costs independent of the amount of power traded.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"monetary amount per time unit","indices":["n"],"evidence_ids":["v141-b-g01-e13","v141-b-g01-e24"]},{"parameter_id":"theta_gamma_uniq_nm","symbol":"\\gamma^{\\mathrm{uniq}}_{nm}","meaning":"Network-charge coefficient under the unique cost-allocation policy, with magnitude one half of the unique unit fee and sign chosen so that the charge contribution for the traded quantity is nonnegative.","value":{"kind":"symbolic","number_value":null,"text_value":"\\pm u^{\\mathrm{uniq}}/2, with sign chosen so that \\gamma^{\\mathrm{uniq}}_{nm}p_{nm}\\ge 0"},"unit":"€/MWh","indices":["n","m"],"evidence_ids":["v141-b-g01-e26"]},{"parameter_id":"theta_gamma_dist_nm","symbol":"\\gamma^{\\mathrm{dist}}_{nm}","meaning":"Network-charge coefficient under the electrical-distance cost-allocation policy, proportional to electrical distance and split equally between the trade endpoints.","value":{"kind":"symbolic","number_value":null,"text_value":"\\pm u^{\\mathrm{dist}}d_{nm}/2, with the prescribed sign convention"},"unit":"€/MWh","indices":["n","m"],"evidence_ids":["v141-b-g01-e27"]},{"parameter_id":"theta_gamma_zone_nm","symbol":"\\gamma^{\\mathrm{zone}}_{nm}","meaning":"Network-charge coefficient under the illustrative uniform-zonal-unit-fee policy, proportional to the number of zones crossed and split equally between the trade endpoints.","value":{"kind":"symbolic","number_value":null,"text_value":"\\pm u^{\\mathrm{zone}}N^{\\mathrm{zone}}_{nm}/2, with the sign convention conserved"},"unit":"€/MWh","indices":["n","m"],"evidence_ids":["v141-b-g02-E13"]},{"parameter_id":"theta_u_uniq","symbol":"u^{\\mathrm{uniq}}","meaning":"Unique unit fee chosen by the system operator for the unique cost-allocation policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/MWh for an hourly time unit","indices":[],"evidence_ids":["v141-b-g01-e26","v141-b-g01-e05"]},{"parameter_id":"theta_u_dist","symbol":"u^{\\mathrm{dist}}","meaning":"Distance unit fee chosen by the system operator for the electrical-distance cost-allocation policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/MWh/distance unit if the same time unit is used","indices":[],"evidence_ids":["v141-b-g01-e27","v141-b-g01-e05"]},{"parameter_id":"theta_u_zone","symbol":"u^{\\mathrm{zone}}","meaning":"Uniform zonal unit fee under the illustrative zonal cost-allocation policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/MWh","indices":[],"evidence_ids":["v141-b-g02-E13","v141-b-g01-e05"]},{"parameter_id":"theta_d_nm","symbol":"d_{nm}","meaning":"Electrical distance between agent n and agent m used by the electrical-distance network-charge policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"distance unit","indices":["n","m"],"evidence_ids":["v141-b-g01-e27","v141-b-g01-e28"]},{"parameter_id":"theta_Nzone_nm","symbol":"N^{\\mathrm{zone}}_{nm}","meaning":"Number of crossed zones for trade p_nm used by the uniform zonal network-charge policy.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"zones (dimensionless count)","indices":["n","m"],"evidence_ids":["v141-b-g02-E13","v141-b-g02-E12"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"mathematical","role":"core","statement":"Each agent's signed monetary outcome equals the sum of bilateral trading prices multiplied by traded powers, minus its network-charge allocation, including the constant charge term. The network-charge portion is reserved to the system operator. Scope: Bilateral real-power trades of each P2P market agent per market time unit.","expression":"\\Lambda_n=\\sum_{m\\in\\omega_n}\\lambda_{nm}p_{nm}-\\Gamma_n,\\quad \\Gamma_n=\\gamma_n^0+\\sum_{m\\in\\omega_n}\\gamma_{nm}p_{nm},\\quad n\\in\\Omega","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_p_nm","x_lambda_nm"],"parameter_refs":["theta_gamma_nm","theta_gamma_n0"],"evidence_ids":["v141-b-g01-e24"]},{"constraint_id":"v141-c-R008-C002","kind":"procedural","role":"core","statement":"Bilateral monetary obligations include an energy-generation-cost component supplemented by a network-charge component that can recover network costs and other operational, tax and policy-related costs. Scope: Cost components of the proposed P2P bilateral contracts.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e04"]},{"constraint_id":"v141-c-R008-C003","kind":"procedural","role":"core","statement":"The fee mechanism covers real-power trades only; reactive-power injection fees are outside its stated scope. Scope: Trade fees considered in the proposed P2P cost-allocation mechanism.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e25"]},{"constraint_id":"v141-c-R008-C004","kind":"mathematical","role":"core","statement":"Each trade endpoint's network-charge coefficient has magnitude one half of the unique unit fee, with its sign chosen so that the charge contribution for the traded quantity is nonnegative. Scope: Network-charge component of bilateral settlement under the unique cost-allocation policy. Condition: Both ends of a trade are assigned equal responsibility.","expression":"\\gamma^{\\mathrm{uniq}}_{nm}=\\pm\\frac{u^{\\mathrm{uniq}}}{2},\\quad \\gamma^{\\mathrm{uniq}}_{nm}p_{nm}\\ge 0,\\quad \\forall(n,m)\\in\\Omega\\times\\omega_n","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_p_nm"],"parameter_refs":["theta_gamma_uniq_nm","theta_u_uniq"],"evidence_ids":["v141-b-g01-e26"]},{"constraint_id":"v141-c-R008-C005","kind":"mathematical","role":"core","statement":"Each trade endpoint's network-charge coefficient has magnitude one half of the distance unit fee multiplied by the electrical distance between the trading agents. Scope: Network-charge component of bilateral settlement under the electrical-distance cost-allocation policy. Condition: Both ends of a trade share responsibility equally and the prescribed charge-sign convention is followed.","expression":"\\gamma^{\\mathrm{dist}}_{nm}=\\pm\\frac{u^{\\mathrm{dist}}d_{nm}}{2},\\quad \\gamma^{\\mathrm{dist}}_{nm}p_{nm}\\ge 0,\\quad \\forall(n,m)\\in\\Omega\\times\\omega_n","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_p_nm"],"parameter_refs":["theta_gamma_dist_nm","theta_u_dist","theta_d_nm"],"evidence_ids":["v141-b-g01-e27"]},{"constraint_id":"v141-c-R008-C006","kind":"mathematical","role":"core","statement":"Each trade endpoint's network-charge coefficient has magnitude one half of the uniform zonal unit fee multiplied by the number of zones crossed by the trade. Scope: Network-charge component of bilateral settlement under the illustrative uniform-zonal-unit-fee policy. Condition: Costs are shared equally between both ends of a trade and the prescribed charge-sign convention is conserved.","expression":"\\gamma^{\\mathrm{zone}}_{nm}=\\pm\\frac{u^{\\mathrm{zone}}N^{\\mathrm{zone}}_{nm}}{2},\\quad \\gamma^{\\mathrm{zone}}_{nm}p_{nm}\\ge 0,\\quad \\forall(n,m)\\in\\Omega\\times\\omega_n","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_p_nm"],"parameter_refs":["theta_gamma_zone_nm","theta_u_zone","theta_Nzone_nm"],"evidence_ids":["v141-b-g02-E13"]},{"constraint_id":"v141-c-R008-C007","kind":"mathematical","role":"supporting","statement":"The system operator's total money collected through network charges equals the sum over all agents of their network-charge allocations, where each agent's allocation is the part reserved to the system operator.","expression":"\\Gamma_{SO}=\\sum_{n\\in\\Omega}\\Gamma_n","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e25"]}],"pi":[{"evidence_id":"v141-b-g01-e04","location":{"location_id":"src-12e1fd7a17-p02-c1r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"gy g , pp y a network charge component. This network charge component is not only to recover all net","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"In contrast, the bilateral contracts considered here have a component that is based on energy generation costs, supplemented by a network charge component. This network charge component is not only to recover all network costs but also other costs e.g. operational, taxes and policy-related costs. Hence, network constraints are not forced directly but rather accommodated through these network charges. Another important benefit of this approach is that market participants have knowledge of network charges prior to the negotiation process. Contrary to a classical economic dispatch, this transparency on network charges enables agents to anticipate on what it will cost them to trade on the network."},{"evidence_id":"v141-b-g01-e24","location":{"location_id":"src-12e1fd7a17-p05-c1r3__v141-a-M01-settlement","page":5,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"whA. Total Fees m. The money paid (resp. received) by agent n for buying if t from (resp. selling to","equation_id":"Eq. (9)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The money paid (resp. received) by agent n for buying from (resp. selling to) agent m is given by the perceived price \\mu_n=\\lambda_{nm}-\\gamma_{nm}, as shown in Appendix A. Network charges represent exogenous costs. Thus, when agent n consumes its \\gamma_{nm} are negative which leads to perceived prices \\mu_n higher than trading prices \\lambda_{nm}. When generating perceived prices are lower than trading prices since parameters \\gamma_{nm} would be positive. The total money paid or received by agent n, for real power bilateral trades per time unit, is expressed by \\Lambda_n=\\sum_{m\\in\\omega_n}\\lambda_{nm}p_{nm}-\\left(\\underbrace{\\gamma_n^0+\\sum_{m\\in\\omega_n}\\gamma_{nm}p_{nm}}_{=\\Gamma_n}\\right), n\\in\\Omega (9); where \\Gamma_n is the part reserved to the system operator."},{"evidence_id":"v141-b-g01-e25","location":{"location_id":"src-12e1fd7a17-p05-c1r4__v141-a-M01-settlement","page":5,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"From the system operator’s point of view, the total amount no of money collected through network cha","equation_id":"Eq. (9)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"From the system operator’s point of view, the total amount of money collected through network charges is simply given by \\Gamma_{SO}=\\sum_{n\\in\\Omega}\\Gamma_n. As mentioned previously, note that the focus is put only on real power trades fees and not reactive power injection’s. This money can be used to cover operation expenses – such as maintenance, power losses, power injection compensations, etc. – as well as investment cost when considering multiple time steps."},{"evidence_id":"v141-b-g01-e26","location":{"location_id":"src-12e1fd7a17-p05-c2r1__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"RICITY MARKETS 2557 to congested areas might not be spurred to behave in a responsible st manner. Mi","equation_id":"Eq. (10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The way to allocate costs is to share them equally between community members. At the image of Paris’ one-way trip public transportation ticket, no discrimination is made between trades. Because of the universality of this policy, agents in recurrently congested areas might not be spurred to behave in a responsible manner. Misbehavior of a few agents may penalize the rest of the community. If network charges are such that both ends of a trade are equally responsible, they can be written as \\gamma_{nm}^{\\mathrm{uniq}}=\\pm\\frac{u^{\\mathrm{uniq}}}{2}, \\forall(n,m)\\in\\Omega\\times\\omega_n, (10); where the sign of \\gamma_{nm}^{\\mathrm{uniq}} is such that \\gamma_{nm}^{\\mathrm{uniq}}p_{nm}\\ge0, so \\ge0 for producers and \\le0 for consumers. Unique unit fee u^{\\mathrm{uniq}} is expressed in €/MWh in the case of an hourly time unit."},{"evidence_id":"v141-b-g01-e27","location":{"location_id":"src-12e1fd7a17-p05-c2r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"ed pressed in € /MWh in the case of an hourly time unit. e. of C. Electrical Distance Cost Allocatio","equation_id":"Eq. (11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"To be more precise in how costs are allocated it is possible to use network charges proportional to the electrical distance between agents. As for cab travels, this cost allocation policy would incite agents to trade with their closest electrical partners. Such policy would reflect that long electric distances are costlier to operate due to power losses for example. However, power losses can not directly be considered as they are quadratic, which can not be superposed. When both ends of a trade equally share responsibility and the previous sign convention is followed, network charges become \\gamma_{nm}^{\\mathrm{dist}}=\\pm\\frac{u^{\\mathrm{dist}}d_{nm}}{2}, \\forall(n,m)\\in\\Omega\\times\\omega_n, (11); where d_nm is the electrical distance between agent n and agent m. Distance unit fee u^{\\mathrm{dist}} is expressed in €/MWh/distance unit if the same time unit is used."},{"evidence_id":"v141-b-g02-E13","location":{"location_id":"src-12e1fd7a17-p06-c2r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"ant sign convention is conserved, uniform zonal network charges become ±uzoneNzone nm , ∀(n, m) ∈Ω ×","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"When costs are equally shared on both ends of a trade and the sign convention is conserved, uniform zonal network charges become \\gamma^{zone}_{nm} = \\pm \\frac{u^{zone} N^{zone}_{nm}}{2}, \\quad \\forall (n,m) \\in \\Omega \\times \\omega_n, (14) where N^{zone}_{nm} corresponds to the number of crossed zone for trade pnm. Zonal unit fee u^{zone} is expressed in € /MWh."},{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-12e1fd7a17-p02-c2r1__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 4, JULY 2019 and costly incentives will be used to ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"costly incentives will be used to allocate grid costs related to the P2P market. The strategy to allocate costs, also called cost allocation policy, imposed to the P2P market participants is chosen by the system operator. The proposed cost allocation policies will be pondered by a coefficient, named unit fee. The unit fee will give a degree of freedom for the system operator to reach cost recovery."},{"evidence_id":"v141-b-g01-e09","location":{"location_id":"src-12e1fd7a17-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"⎜ ⎟ t (2) P = ⎝ ... ... ... ⎠ wo pNΩ 1 · · · pNΩ NΩ deﬁ where pnm is necessarily equal to zero if ag","equation_id":"Eq. (2)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"\\mathbf{P}=\\begin{pmatrix} p_{11} & \\cdots & p_{1N_\\Omega} \\\\ \\vdots & & \\vdots \\\\ p_{N_\\Omega 1} & \\cdots & p_{N_\\Omega N_\\Omega} \\end{pmatrix} (2); where p_{nm} is necessarily equal to zero if agent m is not in agent n’s trading partnership set \\omega_n. Net powers are then obtained by p_n=\\sum_{m\\in\\omega_n}p_{nm} as in (1c). As outlined in (1b), P is skew-symmetric to insure power balance of each trade, so p_{nn}=0. This allows to potentially individualize prices per trade."},{"evidence_id":"v141-b-g01-e10","location":{"location_id":"src-12e1fd7a17-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"⎜ ⎟ t (2) P = ⎝ ... ... ... ⎠ wo pNΩ 1 · · · pNΩ NΩ deﬁ where pnm is necessarily equal to zero if ag","equation_id":"Eq. (1e)-(1g)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In this situation agents can buy a large amount of energy at a low price from one agent to sell it back at a higher price to another. This possibility of arbitraging can be proscribed by limiting the possible amounts traded. Generators, for which p_n\\ge0 and grouped in \\Omega_g, are forbidden to buy power in (1e). On the other hand consumers, for which p_n\\le0 and grouped in \\Omega_c, are forbidden to sell power in (1f). However, prosumers, gathered in \\Omega_p, must still be able to either buy or sell power since they are such that \\underline{p}_n\u003c0\u003c\\overline{p}_n. Power trades of prosumers are bounded by their power boundaries as in (1g)."},{"evidence_id":"v141-b-g01-e13","location":{"location_id":"src-12e1fd7a17-p03-c2r3__v141-a-M01-pricing","page":3,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"t s pu pose. e , egu a at o u ct o h eva uat g et 2) work constraints is be replaced by a cost alloc","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"However, even though (3) enables the system operator to recover congestion related costs, it does not guarantee the recovery of the costs of maintenance, modernization of power lines, taxes, and policies. This paper proposes to replace the regularization function h with exogenous terms. These exogenous terms would aim not only at allocating congestion-related costs but also costs of maintenance and modernization of power lines, taxes, and policies such as e.g. renewable support schemes. Preference prices as introduced in [18] seems a good candidate for this purpose. Then, regularization function h evaluating network constraints is be replaced by a cost allocation function defined as \\Gamma(\\mathbf{P})=\\sum_{n\\in\\Omega}\\left(\\gamma_n^0+\\sum_{m\\in\\omega_n}\\gamma_{nm}p_{nm}\\right) (4); where parameter \\gamma_{nm} is the network charge associated to power trade p_{nm} for the given time step. Constant terms \\gamma_n^0, which do not affect the minimization outcome, allow reflecting costs that are independent of the power traded, such as power line investment and maintenance. Network charges \\gamma_{nm}, detailed in Section III, would then account for congestion-related costs and taxes. Function \\Gamma is separable among participants, and will be integrated in their objective function as it will be further discussed in Section III. Note that \\Gamma also represents the amount of money collected by the system operator from community \\Omega for its use of the power system."},{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-12e1fd7a17-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"a competitive equilibrium which efﬁciency strongly depends on w the chosen network charges. Accordin","equation_id":"Eq. (6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As developed in Appendix B, a decentralized procedure based on the consensus ADMM of [11] is used to solve (5). This decentralized method solves global problem (5) and, hence, leads to a competitive equilibrium which efficiency strongly depends on the chosen network charges. According to [19] ADMM seems well adapted for negotiation mechanisms in smart grids. Several extensions and convergence rate improvements have been proposed in [20]–[23]. Given the focus of this paper is not on scalability a straightforward implementation of consensus ADMM is used. The final decentralized negotiation mechanism reads P_n^{k+1}=\\arg\\min_{P_n} f_n(p_n)+\\gamma_n^0+\\sum_{m\\in\\omega_n}\\left[\\gamma_{nm}p_{nm}+\\lambda_{nm}^k\\left(\\frac{p_{nm}^k-p_{mn}^k}{2}-p_{nm}\\right)+\\frac{\\rho}{2}\\left(\\frac{p_{nm}^k-p_{mn}^k}{2}-p_{nm}\\right)^2\\right] (6a); s.t. p_n=\\sum_{m\\in\\omega_n}p_{nm}; \\underline{p}_n\\le p_n\\le\\overline{p}_n; p_{nm}\\ge0 \\text{ if } n\\in\\Omega_g; p_{nm}\\le0 \\text{ if } n\\in\\Omega_c; \\underline{p}_n\\le p_{nm}\\le\\overline{p}_n \\text{ if } n\\in\\Omega_p (6a); \\lambda_{nm}^{k+1}=\\lambda_{nm}^k-\\rho(p_{nm}^{k+1}+p_{mn}^{k+1})/2 (6b)."},{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-12e1fd7a17-p04-c2r1__v141-a-M01-validation","page":4,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 4, JULY 2019 fn to be closed, proper, and convex is","equation_id":"Eq. (6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"where penalty factor \\rho>0. Element \\lambda_{nm} of matrix \\Lambda corresponds to generation price of electricity for traded volume p_{nm}. Possible trades of agents n can be grouped in variable P_n=(p_{nm})_{m\\in\\omega_n}. According to [11], supposing cost functions f_n to be closed, proper, and convex is a sufficient condition to ensure convergence of (6). This formulation allows to have primal feasibility of constraints (5c)–(5g) at each iteration step. However, primal feasibility of trades reciprocity (5b) is only verified at the limit after convergence. Note that the additional terms of the augmented Lagrangian in (6a) aims at encouraging, economically, an agent n to reach power consensus with its partners."},{"evidence_id":"v141-b-g01-e28","location":{"location_id":"src-12e1fd7a17-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"nt nodes is evaluated by en he Zthil = | Zii + Zll −Zil −Zli | (12) ve where Zil = 1/Yil is an eleme","equation_id":"Eq. (12)","figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The definition of an electrical distance is a crucial issue for this cost allocation policy. [30] recommends two electrical distances, initially developed to allow a better vulnerability assessment through topological visualization of an electrical structure. It is possible to either consider 1) the Thevenin Impedance Distance, where each line is weighed by the norm of its Thevenin impedance after which a shortest path algorithm is performed to obtain the Thevenin electrical distance between two distant nodes, or 2) the Power Transfer Distance, where the absolute value of Power Transfer Distribution Factors induced by a unitary trade are summed. Thevenin electrical distance Z_{il}^{\\mathrm{th}} between two connected nodes is evaluated by Z_{il}^{\\mathrm{th}}=|Z_{ii}+Z_{ll}-Z_{il}-Z_{li}| (12); where Z_il=1/Y_il is an element of bus and branch impedance matrix. If applied to the small example of Figure 1 a, Thevenin impedances are as in Figure 1 b. It is evident that multiple roads are possible for the power to flow between two nodes. But, e.g., for a power injection at node 1 and a withdrawal at node 3 only one Thevenin impedance distance value must prevail. It is proposed to use the shortest path as a metric to reflect the path on which the power exchange as the highest effect. For example, shortest path algorithm of [31] can be used. In the case of Figure 1 b, Thevenin impedance distance between node 1 and node 3 is d_{13}^{\\mathrm{th}}=\\min(Z_{12}^{\\mathrm{th}}+Z_{23}^{\\mathrm{th}},Z_{13}^{\\mathrm{th}})=0.96."},{"evidence_id":"v141-b-g02-E12","location":{"location_id":"src-12e1fd7a17-p06-c1r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III. Exogenous Operation Cost Allocation","anchor_text":"g , p g self-consumption. In this sense, the zonal cost allocation policy A allows to economically i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"A possible way to obtain the network charges is to sum zonal network fees of zones crossed by each trade. As mentioned previously, the electrical path is not unique which could lead to multiple lists of crossed zones. To select only one of them, the shortest electrical path criterion, as defined above with the Thevenin electrical distance, can be taken. then, chosen crossed zones would reflect the most stressed one by a trade. For illustrative simplicity, in this paper the mechanism is simplified by considering a uniform zonal unit fee. This way, the problem of how zonal unit fees are designed between zones is limited. When costs are equally shared on both ends of a trade and the sign convention is conserved..."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-settlement"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e24","quote":"The total money paid or received by agent n, for real power bilateral trades per time unit, is expressed by \\Lambda_n=\\sum_{m\\in\\omega_n}\\lambda_{nm}p_{nm}-\\left(\\underbrace{\\gamma_n^0+\\sum_{m\\in\\omega_n}\\gamma_{nm}p_{nm}}_{=\\Gamma_n}\\right), n\\in\\Omega (9); where \\Gamma_n is the part reserved to the system operator."}],[{"evidence_id":"v141-b-g01-e04","quote":"In contrast, the bilateral contracts considered here have a component that is based on energy generation costs, supplemented by a network charge component. This network charge component is not only to recover all network costs but also other costs e.g. operational, taxes and policy-related costs."}],[{"evidence_id":"v141-b-g01-e25","quote":"As mentioned previously, note that the focus is put only on real power trades fees and not reactive power injection’s."}],[{"evidence_id":"v141-b-g01-e26","quote":"If network charges are such that both ends of a trade are equally responsible, they can be written as \\gamma_{nm}^{\\mathrm{uniq}}=\\pm\\frac{u^{\\mathrm{uniq}}}{2}, \\forall(n,m)\\in\\Omega\\times\\omega_n, (10); where the sign of \\gamma_{nm}^{\\mathrm{uniq}} is such that \\gamma_{nm}^{\\mathrm{uniq}}p_{nm}\\ge0, so \\ge0 for producers and \\le0 for consumers."}],[{"evidence_id":"v141-b-g01-e27","quote":"When both ends of a trade equally share responsibility and the previous sign convention is followed, network charges become \\gamma_{nm}^{\\mathrm{dist}}=\\pm\\frac{u^{\\mathrm{dist}}d_{nm}}{2}, \\forall(n,m)\\in\\Omega\\times\\omega_n, (11); where d_nm is the electrical distance between agent n and agent m."}],[{"evidence_id":"v141-b-g02-E13","quote":"When costs are equally shared on both ends of a trade and the sign convention is conserved, uniform zonal network charges become \\gamma^{zone}_{nm} = \\pm \\frac{u^{zone} N^{zone}_{nm}}{2}, \\quad \\forall (n,m) \\in \\Omega \\times \\omega_n, (14) where N^{zone}_{nm} corresponds to the number of crossed zone for trade pnm."}]],"C2_formalization":{"graph_sha256":"b73a6032b3379a7ba63f86a48075ae04fabf929ef9b673ff2caaab87b3f51618","applicability":"formalized","reason":"The candidate B quotations provide explicit source equations for the settlement payment identity (Eq. 9), the unique, electrical-distance and zonal network-charge coefficients (Eqs. 10, 11 and 14), and the system-operator collection identity. The frozen R008 graph contains only the unary settlement.payment relation and no edges, which is sufficient for these accounting and coefficient-definition relations. B evidence remains unreviewed; this is a source-quotation-based formalization, not an independent source audit.","bindings":[{"object_id":"x_p_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The bilateral traded power p_nm is multiplied by the bilateral trading price in Eq. (9) and is therefore an input to the settlement payment relation."},{"object_id":"x_lambda_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The bilateral trading price lambda_nm enters Eq. (9) as the per-trade price multiplying p_nm in the settlement payment."},{"object_id":"theta_gamma_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The network-charge coefficient gamma_nm enters the deducted Gamma_n term of Eq. (9)."},{"object_id":"theta_gamma_n0","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The constant charge term gamma_n^0 enters the deducted Gamma_n term of Eq. (9)."},{"object_id":"theta_gamma_uniq_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (10) defines the unique-policy network-charge coefficient used in the settlement payment."},{"object_id":"theta_gamma_dist_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (11) defines the electrical-distance network-charge coefficient used in the settlement payment."},{"object_id":"theta_gamma_zone_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (14) defines the uniform-zonal network-charge coefficient used in the settlement payment."},{"object_id":"theta_u_uniq","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The unique unit fee determines the magnitude of gamma^{uniq}_{nm} in Eq. (10) and hence the settlement network charge."},{"object_id":"theta_u_dist","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The distance unit fee determines the magnitude of gamma^{dist}_{nm} in Eq. (11) and hence the settlement network charge."},{"object_id":"theta_u_zone","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The zonal unit fee determines the magnitude of gamma^{zone}_{nm} in Eq. (14) and hence the settlement network charge."},{"object_id":"theta_d_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The electrical distance d_nm scales the network-charge coefficient in Eq. (11) and hence the settlement payment deduction."},{"object_id":"theta_Nzone_nm","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The number of crossed zones N^{zone}_{nm} scales the network-charge coefficient in Eq. (14) and hence the settlement payment deduction."},{"object_id":"v141-c-R008-C001","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (9) is the core settlement payment identity for each agent, directly formalizing the settlement.payment relation."},{"object_id":"v141-c-R008-C004","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (10) defines the unique-policy coefficient embedded in the settlement payment relation; no additional graph edge is required for this unary coefficient definition."},{"object_id":"v141-c-R008-C005","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (11) defines the electrical-distance coefficient embedded in the settlement payment relation; no additional graph edge is required."},{"object_id":"v141-c-R008-C006","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (14) defines the zonal coefficient embedded in the settlement payment relation; no additional graph edge is required."},{"object_id":"v141-c-R008-C007","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The system-operator collection identity aggregates the per-agent network-charge components of the settlement payment relation."}],"revision_requests":[]}},"quarantined_references":[]}});
